import math

def count_zeros(k):
    """Counts the number of zeros in the decimal expansion of an integer k."""
    if k <= 0:
        return 0
    s = str(k)
    return s.count('0')

def analyze_small_cases(L, N_values):
    """
    Tests small 4-digit M values (L=4, M must have no zeros) for given N.
    We only check M values constructed from digits {1, 9} to maximize contrast,
    as these tend to produce larger quotients.
    """
    print(f"--- Analysis for M length L={L} ---")
    # Generate all 4-digit numbers M composed only of {1, ..., 9}
    import itertools
    digits = [str(i) for i in range(1, 10)]
    M_candidates = []
    for combo in itertools.product(digits, repeat=L):
        M_candidates.append(int("".join(combo)))

    results = {}
    for N in N_values:
        max_A = -1
        best_M = None
        print(f"\nChecking N = {N}...")

        for M in M_candidates:
            K = math.floor(M / N)
            A = count_zeros(K)

            if A > max_A:
                max_A = A
                best_M = M

            # Stop early if we find a very high count (e.g., A=2)
            if A >= 2 and N == 3: # Arbitrary stopping condition for demonstration
                 pass

        results[N] = {"max_A": max_A, "M": best_M}

    return results

# Test for L=4 and N in {2, 3, 4, 5}
L = 4
N_values = [2, 3, 4, 5]
test_results = analyze_small_cases(L, N_values)
print("\n--- Final Test Results (L=4) ---")
for N, res in test_results.items():
    print(f"N={N}: Max A found = {res['max_A']} (using M={res['M']})")

